from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(revision_priority, tax_base):
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = ((event.get("revision", 0), pos) if revision_priority == "revision_first"
                   else (sequence, event.get("revision", 0), pos))
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            base = net if tax_base == "discounted" else raw
            tax = rounded(base * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependency_resolver(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        choices.append([None] + versions)

    best = None
    best_vector = None
    for values in product(*choices):
        installed = dict(zip(names, values))
        if any(installed.get(name) is None or not low <= installed[name] <= high
               for name, (low, high) in roots.items()):
            continue
        edges = {name: [] for name, version in installed.items() if version is not None}
        valid = True
        for name, version in installed.items():
            if version is None:
                continue
            row = next(r for r in packages[name] if r["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                chosen_version = installed.get(target)
                if chosen_version is None or not dep["min"] <= chosen_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if any(version is not None and name not in reachable
               for name, version in installed.items()):
            continue
        vector = tuple(-1 if installed[name] is None else installed[name] for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best = vector, {name: version for name, version in installed.items()
                                         if version is not None}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _quota_intervals(data):
    from itertools import combinations

    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        active = []
        feasible = True
        for job in ordered:
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                feasible = False
                break
        if not feasible:
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    remaining = data["coupons"]
    start = data["start"]
    initial = (source, initial_mask, remaining)
    distances = {initial: start}
    queue = [(start, source, initial_mask, remaining)]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            destination = edge["v"]
            next_mask = mask | bit_for.get(destination, 0)
            options = [(edge["duration"], coupons)]
            if coupons:
                discount = edge.get("discount", 0)
                options.append((max(2, edge["duration"] - discount), coupons - 1))
            for duration, next_coupons in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (destination, next_mask, next_coupons)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, destination, next_mask, next_coupons))
    return {"arrival": None}


SOLVERS = {
    "component_01": _ledger("revision_first", "discounted"),
    "component_02": _ledger("sequence_first", "discounted"),
    "component_03": _ledger("revision_first", "original"),
    "component_04": _ledger("sequence_first", "original"),
    "component_05": _ledger("revision_first", "discounted"),
    "component_06": _dependency_resolver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
